import{c as r,Q as e,j as t,m as l}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"RO3台港澳測試即將啟動！開發者日誌透露PC端UI大改進","description":"RO3开发者日志1发布，确认台港澳测试即将开启，PC端UI和操作将尽可能贴近RO1经典体验，副本机制、跑姿、赛季制等细节公开。","frontmatter":{"title":"RO3台港澳測試即將啟動！開發者日誌透露PC端UI大改進","date":"2026-05-27T00:00:00.000Z","description":"RO3开发者日志1发布，确认台港澳测试即将开启，PC端UI和操作将尽可能贴近RO1经典体验，副本机制、跑姿、赛季制等细节公开。"},"headers":[],"relativePath":"news/dev-diary-1-202605.md","filePath":"news/dev-diary-1-202605.md","lastUpdated":1780230216000}'),i={name:"news/dev-diary-1-202605.md"};function o(n,a,s,d,h,c){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="ro3台港澳測試即將啟動-開發者日誌透露pc端ui大改進" tabindex="-1">RO3台港澳測試即將啟動！開發者日誌透露PC端UI大改進 <a class="header-anchor" href="#ro3台港澳測試即將啟動-開發者日誌透露pc端ui大改進" aria-label="Permalink to &quot;RO3台港澳測試即將啟動！開發者日誌透露PC端UI大改進&quot;">​</a></h1><p>2026年5月27日，RO3官方發布了第一期<strong>開發者日誌</strong>，針對台港澳玩家關注的多個問題進行了回應，並確認台港澳測試即將啟動。</p><h2 id="重點資訊" tabindex="-1">重點資訊 <a class="header-anchor" href="#重點資訊" aria-label="Permalink to &quot;重點資訊&quot;">​</a></h2><h3 id="台港澳測試即將到來" tabindex="-1">台港澳測試即將到來 <a class="header-anchor" href="#台港澳測試即將到來" aria-label="Permalink to &quot;台港澳測試即將到來&quot;">​</a></h3><p>開發團隊確認，近期將在台港澳地區進行測試。據巴哈姆特網友透露，<strong>6月初將在Discord開放報名</strong>，屆時玩家可以通過官方Discord頻道獲取測試資格。</p><h3 id="pc端ui與操作大改進" tabindex="-1">PC端UI與操作大改進 <a class="header-anchor" href="#pc端ui與操作大改進" aria-label="Permalink to &quot;PC端UI與操作大改進&quot;">​</a></h3><p>針對先鋒測試中PC玩家反映的操作問題，開發團隊表示：</p><ul><li>PC端UI和操作將<strong>盡可能貼近RO1</strong></li><li>還原PC端遊該有的操作樣態</li><li>不再只有走路——<strong>跑速到達一定值後將自動切換為跑步姿態</strong></li><li>這對老RO玩家來說是一個非常暖心的細節還原</li></ul><h3 id="副本機制設計" tabindex="-1">副本機制設計 <a class="header-anchor" href="#副本機制設計" aria-label="Permalink to &quot;副本機制設計&quot;">​</a></h3><p>未來的副本將包含<strong>機制設計</strong>：</p><ul><li>不再是單純的站樁輸出</li><li>BOSS技能需要躲避和處理機制</li><li>團隊配合更加重要</li><li>類似經典MMO的機制副本</li></ul><h3 id="賽季制確認" tabindex="-1">賽季制確認 <a class="header-anchor" href="#賽季制確認" aria-label="Permalink to &quot;賽季制確認&quot;">​</a></h3><p>再次確認RO3將採用<strong>賽季制</strong>（每季約3-4個月）：</p><ul><li>每個賽季帶來全新內容</li><li>賽季重置部分進度</li><li>鼓勵玩家嘗試不同職業和玩法</li></ul><h2 id="開發者日誌後續" tabindex="-1">開發者日誌後續 <a class="header-anchor" href="#開發者日誌後續" aria-label="Permalink to &quot;開發者日誌後續&quot;">​</a></h2><p>這是RO3官方發布的第一期開發者日誌，未來將定期更新，持續與玩家溝通開發進度。這也是GRAVITY在「全球玩家共創計劃」中的重要一環，讓玩家能夠直接影響遊戲開發方向。</p><h2 id="如何參與測試" tabindex="-1">如何參與測試 <a class="header-anchor" href="#如何參與測試" aria-label="Permalink to &quot;如何參與測試&quot;">​</a></h2><ol><li>加入官方Discord：<a href="https://discord.gg/ro3global" target="_blank" rel="noreferrer">https://discord.gg/ro3global</a></li><li>關注台港澳官方FB粉絲團</li><li>6月初留意Discord測試報名公告</li></ol><blockquote><p>轉載自：<a href="https://forum.gamer.com.tw/C.php?bsn=81475&amp;snA=39" target="_blank" rel="noreferrer">RO3開發者日誌1 - 巴哈姆特</a></p></blockquote>',19)])])}const b=r(i,[["render",o]]);export{u as __pageData,b as default};
